    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nMesomeric (resonance) effect classification.\n\n2. GIVEN:\nSubstituents on conjugated pi systems.\n\n3. FORMULA / PRINCIPLE:\n-M groups possess multiple bonds with a more electronegative atom (e.g. -N=O, -C=O, -C#N).\n\n4. STEP-BY-STEP SOLUTION:\n1. The nitro group (-NO2) contains a nitrogen double-bonded to an electronegative oxygen: -N(=O)->O.\n2. When attached to a conjugated pi system (like benzene), pi electrons are pulled toward oxygen, depleting ring electron density.\n3. This withdrawing resonance effect is classified as -M or -R.\n4. Groups with unshared lone pairs (-OH, -NH2, -OCH3) donate electron pairs into the conjugated system (+M/+R).\n\n5. FINAL ANSWER:\nOption A: -NO2 (nitro group)\n\n6. WHY OTHER OPTIONS ARE WRONG:\nSpecies with pi bonds to electronegative heteroatoms withdraw electrons by resonance (-M).",
